export function validLocalArchive(data){return data?.format==='w-alerter-local-observations'&&data.version===1&&data.metadata?.sourceLicense==='CC BY-NC 4.0'&&data.metadata.commercialDistributionCleared===false&&/^[a-f0-9]{64}$/.test(data.metadata.archiveSha256)&&Array.isArray(data.records)&&data.records.length===data.metadata.recordCount&&data.records.length>0&&data.records.length<=100000&&data.records.every(r=>typeof r.id==='string'&&r.id.length&&r.species==='Megaptera novaeangliae'&&Number.isFinite(r.lat)&&Number.isFinite(r.lon)&&Math.abs(r.lat)<=90&&Math.abs(r.lon)<=180&&typeof r.date==='string'&&r.date.startsWith(String(r.year))&&(r.month===null||Number.isInteger(r.month)&&r.month>=1&&r.month<=12)&&(r.uncertaintyMeters===null||Number.isFinite(r.uncertaintyMeters)&&r.uncertaintyMeters>=0));}
export class ObservationRepository{
  constructor({indexedDB=globalThis.indexedDB}={}){this.indexedDB=indexedDB;this.db=null;this.current=null;this.persistence='memory';}
  async open(){if(this.db)return this.db;if(!this.indexedDB)throw Error('observation_storage_unavailable');this.db=await new Promise((resolve,reject)=>{const q=this.indexedDB.open('w-alerter.observations.v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('archives');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('observation_storage_blocked'));});return this.db;}
  async load(){try{const db=await this.open(),data=await new Promise((resolve,reject)=>{const q=db.transaction('archives').objectStore('archives').get('active');q.onsuccess=()=>resolve(q.result||null);q.onerror=()=>reject(q.error);});if(validLocalArchive(data)){this.current=data;this.persistence='indexeddb';}}catch{this.persistence='memory';}return this.current;}
  async save(data){if(!validLocalArchive(data))throw Error('invalid_local_observation_archive');try{const db=await this.open();await new Promise((resolve,reject)=>{const tx=db.transaction('archives','readwrite');tx.objectStore('archives').put(data,'active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});this.persistence='indexeddb';}catch{this.persistence='memory';}this.current=data;return this.persistence;}
  async remove(){try{const db=await this.open();await new Promise((resolve,reject)=>{const tx=db.transaction('archives','readwrite');tx.objectStore('archives').delete('active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(error){if(this.persistence==='indexeddb')throw error;}this.current=null;}
}
